common_handler:
    /* Save general-purpose registers (order matches frame_t) */
    push %rax
    push %rcx
    push %rdx
    push %rbx
    push %rbp
    push %rsi
    push %rdi
    push %r8
    push %r9
    push %r10
    push %r11
    push %r12
    push %r13
    push %r14
    push %r15

    /* Call handler with rsp pointing to frame_t */
    mov %rsp, %rdi
    call sys_amd64_exception_handler

    /* Handler should not return; if it does, halt */
    cli
    hlt
    jmp .

